function extractTenantContext(request) {
  const claims = verifyAndDecodeToken(request.authToken);
  if (!claims.tenantId) {
    throw new Error('token missing tenant id, reject request');
  }
  return { tenantId: claims.tenantId, userId: claims.userId };
}

async function getInvoiceTool(args, context) {
  const { tenantId } = context;
  if (!tenantId) throw new Error('no tenant context, refusing to run');

  const invoice = await db.collection('invoices').findOne({
    _id: args.invoiceId,
    tenantId,
  });

  if (!invoice) {
    throw new Error('invoice not found');
  }
  return invoice;
}

test('tool never returns another tenant data', async () => {
  await seedInvoice({ tenantId: 'tenant-a', invoiceId: 'inv-1' });

  const result = await getInvoiceTool(
    { invoiceId: 'inv-1' },
    { tenantId: 'tenant-b' }
  );

  expect(result).toBeNull();
});

async function checkTenantRateLimit(tenantId) {
  const key = 'ratelimit:' + tenantId;
  const count = await redis.incr(key);
  if (count === 1) {
    await redis.expire(key, 60);
  }
  if (count > tenantPlanLimits[tenantId]) {
    throw new Error('tenant rate limit exceeded, slow down');
  }
}
